using System.Collections.Generic;
using UnityEngine;

[RequireComponent(typeof(MeshFilter), typeof(MeshRenderer))]
public class RuntimeMeshCombiner : MonoBehaviour
{
    [SerializeField] private bool destroyOriginals = true;

    [ContextMenu("Combinar Malhas")]
    public void CombineMeshes()
    {
        MeshFilter[] meshFilters = GetComponentsInChildren<MeshFilter>(false);
        Dictionary<Material, List<CombineInstance>> materialToCombineInstances = new Dictionary<Material, List<CombineInstance>>();

        Matrix4x4 myTransformMatrix = transform.worldToLocalMatrix;

        for (int i = 0; i < meshFilters.Length; i++)
        {
            MeshFilter mf = meshFilters[i];
            if (mf == this.GetComponent<MeshFilter>()) continue;

            MeshRenderer mr = mf.GetComponent<MeshRenderer>();
            if (mr == null || !mr.enabled || mf.sharedMesh == null) continue;

            Material[] mats = mr.sharedMaterials;
            for (int sub = 0; sub < mf.sharedMesh.subMeshCount; sub++)
            {
                if (sub >= mats.Length) break;
                Material mat = mats[sub];
                if (mat == null) continue;

                if (!materialToCombineInstances.ContainsKey(mat))
                {
                    materialToCombineInstances[mat] = new List<CombineInstance>();
                }

                CombineInstance ci = new CombineInstance();
                ci.mesh = mf.sharedMesh;
                ci.subMeshIndex = sub;
                ci.transform = myTransformMatrix * mf.transform.localToWorldMatrix;
                materialToCombineInstances[mat].Add(ci);
            }

            if (destroyOriginals)
            {
                Destroy(mr);
                Destroy(mf);
            }
            else
            {
                mr.enabled = false;
            }
        }

        List<Material> finalMaterials = new List<Material>();
        List<CombineInstance> finalCombine = new List<CombineInstance>();

        foreach (KeyValuePair<Material, List<CombineInstance>> entry in materialToCombineInstances)
        {
            Mesh subMeshCombined = new Mesh();
            subMeshCombined.indexFormat = UnityEngine.Rendering.IndexFormat.UInt32;
            subMeshCombined.CombineMeshes(entry.Value.ToArray(), true, true);

            CombineInstance ci = new CombineInstance();
            ci.mesh = subMeshCombined;
            ci.subMeshIndex = 0;
            ci.transform = Matrix4x4.identity;

            finalCombine.Add(ci);
            finalMaterials.Add(entry.Key);
        }

        Mesh finalMesh = new Mesh();
        finalMesh.name = "CombinedMesh_" + gameObject.name;
        finalMesh.indexFormat = UnityEngine.Rendering.IndexFormat.UInt32;
        finalMesh.CombineMeshes(finalCombine.ToArray(), false, false);

        GetComponent<MeshFilter>().sharedMesh = finalMesh;
        GetComponent<MeshRenderer>().sharedMaterials = finalMaterials.ToArray();
    }
}

using UnityEngine;
using UnityEngine.Rendering;

public class PerformanceScaler : MonoBehaviour
{
    [SerializeField] private float targetFrameRate = 60.0f;
    [SerializeField] private float minResolutionScale = 0.70f;
    [SerializeField] private float maxResolutionScale = 1.0f;
    private float currentScale = 1.0f;

    void Awake()
    {
        Application.targetFrameRate = 60;
        QualitySettings.vSyncCount = 0;
    }

    void Update()
    {
        float currentFps = 1.0f / Mathf.Max(Time.unscaledDeltaTime, 0.0001f);
        if (currentFps < targetFrameRate - 5f && currentScale > minResolutionScale)
        {
            currentScale = Mathf.Max(minResolutionScale, currentScale - 0.05f * Time.unscaledDeltaTime);
            ScalableBufferManager.ResizeBuffers(currentScale, currentScale);
        }
        else if (currentFps >= targetFrameRate && currentScale < maxResolutionScale)
        {
            currentScale = Mathf.Min(maxResolutionScale, currentScale + 0.02f * Time.unscaledDeltaTime);
            ScalableBufferManager.ResizeBuffers(currentScale, currentScale);
        }
    }
}

using System.Collections.Generic;
using UnityEngine;

public class SimpleObjectPool : MonoBehaviour
{
    public static SimpleObjectPool Instance { get; private set; }
    [SerializeField] private GameObject prefab;
    [SerializeField] private int initialSize = 50;
    private readonly Queue<GameObject> pool = new Queue<GameObject>();

    void Awake()
    {
        Instance = this;
        for (int i = 0; i < initialSize; i++)
        {
            GameObject obj = Instantiate(prefab, transform);
            obj.SetActive(false);
            pool.Enqueue(obj);
        }
    }

    public GameObject Get()
    {
        GameObject obj = pool.Count > 0 ? pool.Dequeue() : Instantiate(prefab, transform);
        obj.SetActive(true);
        return obj;
    }

    public void ReturnToPool(GameObject obj)
    {
        obj.SetActive(false);
        pool.Enqueue(obj);
    }
}

using UnityEngine;

namespace PerformanceAdvisor.StressTest
{
    public class StressTestScene : MonoBehaviour
    {
        [SerializeField] private int bufferSize = 1024;
        private byte[] cachedBuffer;
        private float timer;

        private void Awake()
        {
            // Pré-aloca os recursos necessários uma única vez na inicialização
            cachedBuffer = new byte[bufferSize];
        }

        private void Update()
        {
            // Reutiliza buffers e estruturas existentes sem chamar 'new' repetidamente a cada frame
            ExecuteLogicZeroAlloc(cachedBuffer);
        }

        private void ExecuteLogicZeroAlloc(byte[] workingBuffer)
        {
            for (int i = 0; i < workingBuffer.Length; i++)
            {
                workingBuffer[i] = (byte)(i % 256);
            }
        }
    }
}
